-- Interviews generated by the Vapi Generator Assistant.
--
-- Writes: only the server (`/api/vapi/generate-interview`) using the
--         Supabase secret key, with user_id taken from a verified,
--         server-signed capability token.
-- Reads:   the owning user via RLS with their normal session (SELECT only).
-- Deletes: not exposed to browsers. Each row doubles as the single-use
--          consumption record for its capability token (generation_id), so
--          letting the owner delete it would let an unexpired token be
--          replayed to trigger another paid LLM call and save again.
--
-- Deploy manually (see VAPI_SETUP.md): Supabase Dashboard > SQL Editor,
-- or `supabase db push` if you use the Supabase CLI with a linked project.

create table if not exists public.interviews (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references auth.users (id) on delete cascade,
  -- jti of the capability token; makes each capability single-use.
  generation_id uuid not null unique,
  role          text not null check (char_length(role) between 1 and 80),
  level         text not null check (char_length(level) between 1 and 40),
  type          text not null check (type in ('technical', 'behavioral', 'mixed')),
  techstack     text[] not null default '{}'
                check (cardinality(techstack) between 1 and 12),
  questions     jsonb not null
                check (
                  jsonb_typeof(questions) = 'array'
                  and jsonb_array_length(questions) between 1 and 10
                ),
  created_at    timestamptz not null default now()
);

create index if not exists interviews_user_id_created_at_idx
  on public.interviews (user_id, created_at desc);

alter table public.interviews enable row level security;

-- Explicit grants (do not rely on default privileges).
revoke all on table public.interviews from anon, authenticated;
grant select on table public.interviews to authenticated;
grant all on table public.interviews to service_role;

drop policy if exists "Users can view their own interviews" on public.interviews;
create policy "Users can view their own interviews"
  on public.interviews
  for select
  to authenticated
  using ((select auth.uid()) = user_id);

-- Intentionally no INSERT/UPDATE/DELETE policies (or grants) for
-- anon/authenticated: browsers cannot create, modify or delete interviews.
-- DELETE in particular must stay server-only: deleting a row would
-- re-enable its capability token for replay (see header comment).
